<?php
if($page==='booking'){
  $u=require_auth();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT b.*,l.name location_name,l.address,l.city,l.country,l.opening_hours FROM bookings b JOIN locations l ON l.id=b.location_id WHERE b.id=? AND b.user_id=? LIMIT 1');$s->execute([$id,$u['id']]);$b=$s->fetch();if(!$b){http_response_code(404);exit('Booking not found.');}$r=$pdo->prepare('SELECT id FROM reviews WHERE booking_id=?');$r->execute([$id]);$hasReview=(bool)$r->fetch();layout_start('Booking '.$b['code']);?>
  <section class="container section booking-detail"><a class="back" href="<?=e(app_url(['page'=>'dashboard']))?>">← My bookings</a><div class="section-head"><div><span class="status status-<?=e($b['status'])?>"><?=e(str_replace('_',' ',$b['status']))?></span><h1><?=e($b['location_name'])?></h1><p><?=e($b['address'])?>, <?=e($b['city'])?></p></div><div class="code-card"><small>Booking code</small><strong><?=e($b['code'])?></strong></div></div><div class="summary-grid"><div class="panel"><h3>Drop-off</h3><strong><?=date('D, M j Y',strtotime($b['dropoff_at']))?></strong><p><?=date('g:i A',strtotime($b['dropoff_at']))?></p></div><div class="panel"><h3>Pick-up</h3><strong><?=date('D, M j Y',strtotime($b['pickup_at']))?></strong><p><?=date('g:i A',strtotime($b['pickup_at']))?></p></div><div class="panel"><h3>Storage</h3><strong><?=(int)$b['bags']?> bag<?=(int)$b['bags']>1?'s':''?></strong><p><?=(int)$b['days']?> day<?=(int)$b['days']>1?'s':''?></p></div><div class="panel"><h3>Total</h3><strong><?=e(money((float)$b['total_amount']))?></strong><p>Payment: <?=e($b['payment_status'])?></p></div></div><div class="panel"><h2>At the location</h2><p>Show your booking code <strong><?=e($b['code'])?></strong> at drop-off. Opening hours: <?=e($b['opening_hours'])?>.</p><?php if($b['notes']):?><p><strong>Your note:</strong> <?=e($b['notes'])?></p><?php endif;?></div><?php if($b['status']==='confirmed'):?><form method="post" class="inline-form" onsubmit="return confirm('Cancel this booking?')"><?=csrf_field()?><input type="hidden" name="action" value="cancel-booking"><input type="hidden" name="booking_id" value="<?=$id?>"><button class="btn btn-danger" type="submit">Cancel booking</button></form><?php endif;?><?php if($b['status']==='completed'&&!$hasReview):?><div class="panel"><h2>How was it?</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="add-review"><input type="hidden" name="booking_id" value="<?=$id?>"><label>Rating<select name="rating"><option value="5">5 — Excellent</option><option value="4">4 — Good</option><option value="3">3 — Okay</option><option value="2">2 — Poor</option><option value="1">1 — Bad</option></select></label><label>Review<textarea name="comment" rows="4"></textarea></label><button class="btn" type="submit">Submit review</button></form></div><?php endif;?></section>
  <?php layout_end();exit;
}
